INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'What is a ''healds capacity'' limitation, and why does it matter when designing a complex pattern weave on a dobby loom?', '["Each heald frame/heald can only hold so many warp ends without overcrowding; complex patterns needing many distinct warp groups may exceed available healds/frames, requiring a jacquard instead","Healds capacity refers only to how much dye a heald can absorb, unrelated to weave design","There is no such thing as a healds capacity limitation in any loom","Healds capacity only limits the maximum possible fabric width, not pattern complexity"]'::jsonb, 'Each heald frame/heald can only hold so many warp ends without overcrowding; complex patterns needing many distinct warp groups may exceed available healds/frames, requiring a jacquard instead', 'If a desired pattern requires more independently-controlled warp groups than the available heald frames (or more ends per heald than is practical without overcrowding/abrasion issues), the dobby system reaches its practical limit — pushing the designer toward a jacquard mechanism instead for that level of complexity.', 2, '{"heald-capacity"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'What is the general reason ''denim'' fabric is traditionally woven as a warp-faced twill (typically 3x1)?', '["This structure puts more (often indigo-dyed) warp yarn on the fabric face, creating denim''s characteristic blue face/white back appearance while providing twill''s durability","Denim is always woven as a plain weave, not any form of twill","Warp-faced twill has no relationship to denim''s characteristic two-tone (blue/white) appearance","Denim uses zero weft yarn, making the ''warp-faced'' distinction meaningless"]'::jsonb, 'This structure puts more (often indigo-dyed) warp yarn on the fabric face, creating denim''s characteristic blue face/white back appearance while providing twill''s durability', 'In a warp-faced twill like denim''s typical 3x1 structure, the (usually indigo-dyed) warp yarn dominates the face side while the (usually undyed/white) weft shows more on the back — creating denim''s iconic blue-face/lighter-back look, while the twill structure itself contributes durability/abrasion resistance.', 2, '{"denim-twill"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'Why does denim fabric typically fade (lighten) with wear and washing in a way that reveals the underlying twill/warp structure?', '["Since only the warp yarn is typically dyed (often with indigo, which sits more on the fiber surface rather than penetrating fully), surface abrasion/washing gradually removes surface dye, revealing the lighter core/weft beneath","Denim fading has no relationship to which yarn (warp or weft) was originally dyed","Denim fabric contains no dye at all; the blue color comes entirely from the fiber''s natural pigment","Fading occurs uniformly regardless of the weave structure or which yarn was dyed"]'::jsonb, 'Since only the warp yarn is typically dyed (often with indigo, which sits more on the fiber surface rather than penetrating fully), surface abrasion/washing gradually removes surface dye, revealing the lighter core/weft beneath', 'Indigo dye characteristically doesn''t fully penetrate the cotton fiber core, remaining more concentrated near the yarn''s surface; combined with typically dyeing only the warp yarn, repeated abrasion/washing progressively removes this surface dye, revealing the lighter, undyed weft/fiber core beneath — the classic denim fading look, following the twill''s diagonal structure.', 2, '{"denim-fading","indigo-dye"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'What does ''reed width'' (the total width of the reed used on a loom) need to accommodate, beyond just the finished fabric width?', '["The finished fabric width PLUS the width lost to weaving-in shrinkage/contraction (takeup) and selvedge allowances","Reed width is always identical to the finished fabric''s exact final width with zero adjustment needed","Reed width only relates to warp yarn count, unrelated to fabric width at all","Reed width is determined solely by the loom''s total physical size, unrelated to the fabric being woven"]'::jsonb, 'The finished fabric width PLUS the width lost to weaving-in shrinkage/contraction (takeup) and selvedge allowances', 'Since fabric typically contracts somewhat in width during weaving (as weft interlaces and pulls warp together) and needs selvedge allowance at the edges, the reed must be set up wider than the intended FINISHED fabric width to compensate for this weaving-in contraction and edge requirements.', 2, '{"reed-width-calculation"}'::text[]);
